    const legacyType={'Xét nghiệm':'Lab test','Chẩn đoán hình ảnh':'Imaging'};
    const toOwner=v=>legacyOwner[v]||v;
    const toDoctor=v=>String(v||'').replace(/^BS\. /,'Dr. ');
