    for(const r of data.results){const s=baseline.results.find(v=>v.id===r.id);if(s)Object.assign(r,{title:s.title,type:s.type,doctor:s.doctor});else Object.assign(r,{type:legacyType[r.type]||r.type,doctor:toDoctor(r.doctor)})}
    for(const t of data.doctorTasks){const s=baseline.doctorTasks.find(v=>v.id===t.id);if(s)Object.assign(t,{...structuredClone(s),done:t.done});else t.owner=toOwner(t.owner)}
    for(const n of Object.values(data.resultNexts))if(n)n.owner=toOwner(n.owner);
    delete data.nursingTasks;
