      settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.2.2-2.8 2.8-.2-.2A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 1.6v.3h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.2.2-2.8-2.8.2-.2A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.6-1H2.7v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.1 7l2.8-2.8.2.2A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.3h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.2-.2 2.8 2.8-.2.2A1.7 1.7 0 0 0 19.4 9a1.7 1.7 0 0 0 1.6 1h.3v4H21a1.7 1.7 0 0 0-1.6 1Z"/>',
